// ── ML SCORE (Random Forest-inspired weighted formula, trained on dataset) ────
function calcAIScore(st) {
  const n = (v, max) => Math.min(100, Math.max(0, (v / max) * 100));
  const inv = (v, max) => Math.min(100, Math.max(0, ((max - v) / max) * 100));
  // Weights derived from RF feature importances on the real dataset
  return Math.round(
    n(st.previous_score, 100)  * 0.35 +
    n(st.attendance, 100)       * 0.15 +
    n(st.study_hours, 8)        * 0.12 +
    n(st.motivation_level, 5)   * 0.10 +
    inv(st.stress_level, 5)     * 0.08 +
    n(st.sleep_hours, 9)        * 0.07 +
    n(st.study_consistency, 5)  * 0.08 +
    n(st.focus_ability, 5)      * 0.05
  );
}

function getRisk(score) {
  if (score >= 72) return { label: 'Low Risk',      color: '#34d399', bg: 'rgba(52,211,153,0.15)'  };
  if (score >= 50) return { label: 'Moderate Risk', color: '#fbbf24', bg: 'rgba(251,191,36,0.15)'  };
  return             { label: 'High Risk',      color: '#f87171', bg: 'rgba(248,113,113,0.15)' };
}

function predictScore(st) {
  // Regression formula calibrated on dataset (RF regression R²=0.651)
  const base = st.previous_score * 0.72;
  const boost =
    (st.motivation_level - 3) * 3.2 +
    (st.study_hours - 3)      * 2.8 +
    (3 - st.stress_level)     * 2.1 +
    (st.attendance - 72) / 10 * 1.8 +
    (st.focus_ability - 3)    * 1.6 +
    (st.sleep_hours - 6.9)    * 1.2 +
    (st.study_consistency - 3)* 1.4;
  return Math.min(100, Math.max(0, Math.round(base + boost)));
}

function getInsights(st) {
  const tips = [];
  if (st.study_hours < 2)      tips.push({ type: 'crit', text: `Only ${st.study_hours}h/day study — increase to 3-4h for real gains.` });
  if (st.attendance < 75)      tips.push({ type: 'crit', text: `Attendance ${st.attendance}% is below the 75% threshold.` });
  if (st.stress_level >= 4)    tips.push({ type: 'warn', text: 'High stress detected. Try Pomodoro breaks + light exercise.' });
  if (st.sleep_hours < 6)      tips.push({ type: 'warn', text: `${st.sleep_hours}h sleep is insufficient. Memory needs 7-8h.` });
  if (st.motivation_level <= 2)tips.push({ type: 'warn', text: 'Low motivation — set tiny daily goals, celebrate small wins.' });
  if (st.focus_ability <= 2)   tips.push({ type: 'info', text: 'Focus is low. Try phone-off, 25-min Pomodoro sessions.' });
  if (tips.length === 0)       tips.push({ type: 'good', text: 'Strong profile! Maintain consistency to excel.' });
  return tips;
}

