// ── SEARCH / PICKER MODAL ─────────────────────────────────────────────────────
function StudentPicker({ targetIdx, targetColor, onSelect, onClose }) {
  const [query, setQuery] = useState('');
  const [filterStream, setFilterStream] = useState('All');
  const [filterEdu, setFilterEdu] = useState('All');

  const streams = ['All', ...Array.from(new Set(FULL_DATASET.map(s => s.stream)))];
  const edus    = ['All', ...Array.from(new Set(FULL_DATASET.map(s => s.edu)))];

  const filtered = useMemo(() => {
    const q = query.toLowerCase();
    return FULL_DATASET.filter(s => {
      const matchQ = !q ||
        s.name.toLowerCase().includes(q) ||
        s.stream.toLowerCase().includes(q) ||
        s.gender.toLowerCase().includes(q) ||
        String(s.previous_score).includes(q);
      const matchStr = filterStream === 'All' || s.stream === filterStream;
      const matchEdu = filterEdu === 'All' || s.edu === filterEdu;
      return matchQ && matchStr && matchEdu;
    });
  }, [query, filterStream, filterEdu]);

  return (
    <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.75)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20 }}>
      <div style={{ background: '#111827', borderRadius: 16, width: '100%', maxWidth: 560, maxHeight: '82vh', display: 'flex', flexDirection: 'column', border: '1px solid rgba(255,255,255,0.1)', overflow: 'hidden' }}>
        
        {/* Header */}
        <div style={{ padding: '16px 20px', borderBottom: '1px solid rgba(255,255,255,0.07)', display: 'flex', alignItems: 'center', justifyContent: 'space-between', background: 'rgba(99,102,241,0.08)' }}>
          <div>
            <div style={{ fontSize: 15, fontWeight: 700, color: '#e2e8f0' }}>Load from Dataset</div>
            <div style={{ fontSize: 11.5, color: '#94a3b8', marginTop: 2 }}>
              238 real student responses — loading into&nbsp;
              <span style={{ color: targetColor, fontWeight: 700 }}>Student {String.fromCharCode(65 + targetIdx)}</span>
            </div>
          </div>
          <button onClick={onClose} style={{ background: 'none', border: 'none', color: '#64748b', fontSize: 20, cursor: 'pointer', padding: 4 }}>✕</button>
        </div>

        {/* Filters */}
        <div style={{ padding: '12px 20px', borderBottom: '1px solid rgba(255,255,255,0.07)', display: 'flex', gap: 10, flexWrap: 'wrap' }}>
          <input value={query} onChange={e => setQuery(e.target.value)}
            placeholder="Search by name, stream, score…"
            style={{ ...S.input, flex: 1, minWidth: 160, padding: '7px 12px' }} />
          <select value={filterStream} onChange={e => setFilterStream(e.target.value)} style={{ ...S.select, width: 'auto', padding: '7px 10px' }}>
            {streams.map(s => <option key={s}>{s}</option>)}
          </select>
          <select value={filterEdu} onChange={e => setFilterEdu(e.target.value)} style={{ ...S.select, width: 'auto', padding: '7px 10px' }}>
            {edus.map(s => <option key={s}>{s}</option>)}
          </select>
        </div>

        <div style={{ fontSize: 11, color: '#64748b', padding: '6px 20px 0' }}>
          {filtered.length} of 238 students
        </div>

        {/* List */}
        <div style={{ overflowY: 'auto', padding: '8px 20px 20px', flex: 1 }}>
          {filtered.map(st => {
            const score = calcAIScore(st);
            const risk  = getRisk(score);
            return (
              <div key={st.id} onClick={() => onSelect(st)}
                style={{ padding: '11px 14px', borderRadius: 9, marginBottom: 7, background: '#1c2436', cursor: 'pointer', border: '1px solid rgba(255,255,255,0.06)', transition: 'border-color .15s' }}
                onMouseEnter={e => e.currentTarget.style.borderColor = targetColor}
                onMouseLeave={e => e.currentTarget.style.borderColor = 'rgba(255,255,255,0.06)'}
              >
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <div style={{ fontWeight: 600, fontSize: 13, color: '#e2e8f0' }}>{st.name}</div>
                  <span style={{ fontSize: 10.5, padding: '2px 8px', borderRadius: 999, background: risk.bg, color: risk.color, fontWeight: 600 }}>{risk.label}</span>
                </div>
                <div style={{ display: 'flex', gap: 14, marginTop: 5, fontSize: 11, color: '#94a3b8', flexWrap: 'wrap' }}>
                  <span>{st.gender} · {st.stream} · {st.edu}</span>
                  <span>📊 {st.previous_score}%</span>
                  <span>📅 {st.attendance}%</span>
                  <span>📚 {st.study_hours}h</span>
                  <span>🎯 Expected: {st.expected_score}%</span>
                </div>
              </div>
            );
          })}
          {filtered.length === 0 && (
            <div style={{ textAlign: 'center', color: '#475569', fontSize: 13, padding: '32px 0' }}>No students match your filters.</div>
          )}
        </div>
      </div>
    </div>
  );
}

// ── MAIN COMPONENT ─────────────────────────────────────────────────────────────
export default function StudentComparePage() {
  const [students, setStudents]     = useState(INITIAL_STUDENTS);
  const [activeIdx, setActiveIdx]   = useState(0);
  const [pickerFor, setPickerFor]   = useState(null); // null | index
  const [inputMode, setInputMode]   = useState('manual'); // 'manual' | 'dataset'

  const update = (idx, key, val) =>
    setStudents(s => s.map((st, i) => i === idx ? { ...st, [key]: val } : st));

  const addStudent = () => {
    if (students.length < 4) {
      const idx = students.length;
      setStudents(s => [...s, { ...DEFAULTS, name: `Student ${String.fromCharCode(65 + idx)}` }]);
      setActiveIdx(idx);
    }
  };

  const removeStudent = (idx) => {
    if (students.length <= 2) return;
    setStudents(s => s.filter((_, i) => i !== idx));
    setActiveIdx(prev => Math.max(0, prev >= idx ? prev - 1 : prev));
  };

  const loadFromDataset = (st, idx) => {
    setStudents(s => s.map((old, i) => i === idx ? {
      ...old,
      name: st.name,
      gender: st.gender,
      edu: st.edu,
      stream: st.stream,
      previous_score: st.previous_score,
      attendance: st.attendance,
      study_hours: st.study_hours,
      study_consistency: st.study_consistency,
      sleep_hours: st.sleep_hours,
      stress_level: st.stress_level,
      motivation_level: st.motivation_level,
      exam_anxiety: st.exam_anxiety,
      self_confidence: st.self_confidence,
      focus_ability: st.focus_ability,
      family_support: st.family_support,
      expected_score: st.expected_score,
    } : old));
    setPickerFor(null);
  };

  // Chart data
  const radarData = METRICS.map(m => {
    const obj = { metric: m.label };
    students.forEach((st, i) => {
      const raw = m.invert
        ? ((m.max - st[m.key]) / m.max) * 100
        : (st[m.key] / m.max) * 100;
      obj[st.name || `S${i+1}`] = Math.round(Math.min(100, Math.max(0, raw)));
    });
    return obj;
  });

  const barData = METRICS.map(m => {
    const obj = { name: m.label };
    students.forEach((st, i) => { obj[st.name || `S${i+1}`] = Number(st[m.key]) || 0; });
    return obj;
  });

  const active = students[activeIdx];
  const activeColor = COLORS[activeIdx];

  return (
    <div style={S.root}>

      {/* ── TAB ROW ─────────────────────────────────────── */}
      <div style={{ display: 'flex', gap: 8, marginBottom: 20, flexWrap: 'wrap', alignItems: 'center' }}>
        {students.map((st, i) => (
          <button key={i} onClick={() => setActiveIdx(i)} style={{
            padding: '7px 16px', borderRadius: 999, fontSize: 13, cursor: 'pointer', fontWeight: 600,
            background: activeIdx === i ? COLORS[i] : 'var(--color-background-secondary)',
            color: activeIdx === i ? '#fff' : 'var(--color-text-secondary)',
            border: `1px solid ${activeIdx === i ? COLORS[i] : 'var(--color-border-secondary)'}`,
            fontFamily: 'inherit', display: 'flex', alignItems: 'center', gap: 6,
          }}>
            <span style={{ width: 8, height: 8, borderRadius: '50%', background: COLORS[i], display: 'inline-block', opacity: activeIdx === i ? 0 : 1 }}></span>
            {st.name || `Student ${i+1}`}
          </button>
        ))}
        {students.length < 4 && (
          <button onClick={addStudent} style={S.btn('transparent','var(--color-text-secondary)','1px dashed var(--color-border-secondary)')}>
            + Add Student
          </button>
        )}
        {students.length > 2 && (
          <button onClick={() => removeStudent(activeIdx)} style={S.btn('rgba(248,113,113,0.1)','#f87171','1px solid rgba(248,113,113,0.25)')}>
            − Remove
          </button>
        )}
      </div>

      {/* ── INPUT PANEL ─────────────────────────────────── */}
      <div style={{ ...S.card, borderColor: `${activeColor}30` }}>

        {/* Header row */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 18, flexWrap: 'wrap' }}>
          <div style={{ width: 38, height: 38, borderRadius: '50%', background: COLORS_BG[activeIdx], border: `2px solid ${activeColor}50`, display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 700, fontSize: 15, color: activeColor }}>
            {String.fromCharCode(65 + activeIdx)}
          </div>
          <input
            value={active.name}
            onChange={e => update(activeIdx, 'name', e.target.value)}
            placeholder={`Student ${String.fromCharCode(65 + activeIdx)}`}
            style={{ ...S.input, fontSize: 15, fontWeight: 600, flex: 1, minWidth: 140, border: 'none', background: 'transparent', padding: '4px 0' }}
          />
          {/* Mode toggle */}
          <div style={{ display: 'flex', gap: 6, marginLeft: 'auto' }}>
            <button
              onClick={() => setInputMode('manual')}
              style={S.btn(inputMode==='manual' ? `${activeColor}20` : 'transparent', inputMode==='manual' ? activeColor : 'var(--color-text-secondary)', `1px solid ${inputMode==='manual' ? activeColor+'60' : 'var(--color-border-secondary)'}`)}>
              ✏️ Manual
            </button>
            <button
              onClick={() => { setPickerFor(activeIdx); setInputMode('dataset'); }}
              style={S.btn(inputMode==='dataset' ? `${activeColor}20` : 'transparent', inputMode==='dataset' ? activeColor : 'var(--color-text-secondary)', `1px solid ${inputMode==='dataset' ? activeColor+'60' : 'var(--color-border-secondary)'}`)}>
              📂 Load from Dataset
            </button>
          </div>
        </div>

        {/* Basic fields row */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 12, marginBottom: 16 }}>
          {[
            { label: 'Gender', key: 'gender', opts: ['Male','Female'] },
            { label: 'Education', key: 'edu', opts: ['School','Undergraduate','Postgraduate'] },
            { label: 'Stream', key: 'stream', opts: ['Engineering','Science','Commerce','Arts','Other'] },
          ].map(f => (
            <div key={f.key}>
              <label style={S.label}>{f.label}</label>
              <select value={active[f.key]} onChange={e => update(activeIdx, f.key, e.target.value)} style={S.select}>
                {f.opts.map(o => <option key={o}>{o}</option>)}
              </select>
            </div>
          ))}
        </div>

        {/* Sliders */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2,1fr)', gap: '10px 20px' }}>
          {METRICS.map(m => (
            <div key={m.key}>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 4 }}>
                <span style={{ fontSize: 11.5, color: 'var(--color-text-secondary)' }}>{m.label}</span>
                <span style={S.rangeVal(activeColor)}>{active[m.key]}{m.unit}</span>
              </div>
              <input type="range"
                min={m.key === 'previous_score' || m.key === 'attendance' ? 0 : m.key === 'sleep_hours' ? 3 : 1}
                max={m.max}
                step={m.max <= 5 ? 1 : m.max <= 12 ? 0.5 : 1}
                value={active[m.key]}
                onChange={e => update(activeIdx, m.key, parseFloat(e.target.value))}
                style={{ width: '100%', accentColor: activeColor }}
              />
            </div>
          ))}
        </div>

        {/* Per-student load button inline */}
        <button
          onClick={() => setPickerFor(activeIdx)}
          style={{ ...S.btn(`${activeColor}15`, activeColor, `1px solid ${activeColor}30`), marginTop: 16, fontSize: 12 }}>
          📂 Load different student from dataset →
        </button>
      </div>

      {/* ── AI SCORE CARDS ──────────────────────────────── */}
      <div style={{ display: 'grid', gridTemplateColumns: `repeat(${students.length},1fr)`, gap: 12, marginBottom: 16 }}>
        {students.map((st, i) => {
          const score = calcAIScore(st);
          const risk  = getRisk(score);
          const pred  = predictScore(st);
          return (
            <div key={i} style={{ background: 'var(--color-background-secondary)', border: `1px solid ${COLORS[i]}30`, borderRadius: 12, padding: '18px 16px', textAlign: 'center' }}>
              <div style={{ fontSize: 11, color: 'var(--color-text-tertiary)', marginBottom: 2, fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.6px' }}>{st.name || `Student ${i+1}`}</div>
              <div style={{ fontSize: 42, fontWeight: 800, color: COLORS[i], lineHeight: 1.1, margin: '8px 0 4px' }}>{score}</div>
              <div style={{ fontSize: 11, color: 'var(--color-text-secondary)', marginBottom: 10 }}>AI Score</div>
              <span style={{ fontSize: 11, padding: '4px 11px', borderRadius: 999, background: risk.bg, color: risk.color, fontWeight: 700 }}>{risk.label}</span>
              <div style={{ marginTop: 12, padding: '8px 0', borderTop: '1px solid rgba(255,255,255,0.06)' }}>
                <div style={{ fontSize: 11, color: 'var(--color-text-tertiary)', marginBottom: 2 }}>Predicted Score</div>
                <div style={{ fontSize: 20, fontWeight: 700, color: COLORS[i] }}>{pred}%</div>
              </div>
              {st.expected_score ? (
                <div style={{ marginTop: 6, padding: '6px 0', borderTop: '1px solid rgba(255,255,255,0.06)' }}>
                  <div style={{ fontSize: 11, color: 'var(--color-text-tertiary)', marginBottom: 2 }}>Expected (Dataset)</div>
                  <div style={{ fontSize: 14, fontWeight: 600, color: 'var(--color-text-secondary)' }}>{st.expected_score}%</div>
                </div>
              ) : null}
            </div>
          );
        })}
      </div>

      {/* ── INSIGHTS SIDE BY SIDE ───────────────────────── */}
      <div style={{ display: 'grid', gridTemplateColumns: `repeat(${students.length},1fr)`, gap: 12, marginBottom: 16 }}>
        {students.map((st, i) => (
          <div key={i} style={{ ...S.card, marginBottom: 0 }}>
            <div style={{ fontSize: 12, fontWeight: 700, color: COLORS[i], marginBottom: 10, textTransform: 'uppercase', letterSpacing: '0.6px' }}>{st.name} · Insights</div>
            {getInsights(st).map((ins, j) => (
              <div key={j} style={S.insight(ins.type)}>{ins.text}</div>
            ))}
          </div>
        ))}
      </div>

      {/* ── RADAR ───────────────────────────────────────── */}
      <div style={{ ...S.card }}>
        <div style={{ fontSize: 13, fontWeight: 600, marginBottom: 14, display: 'flex', alignItems: 'center', gap: 8 }}>
          Radar Comparison
          <span style={{ fontSize: 11, color: 'var(--color-text-tertiary)', fontWeight: 400 }}>— normalised 0-100</span>
        </div>
        <ResponsiveContainer width="100%" height={280}>
          <RadarChart data={radarData} margin={{ top: 10, right: 30, bottom: 10, left: 30 }}>
            <PolarGrid stroke="rgba(255,255,255,0.07)" />
            <PolarAngleAxis dataKey="metric" tick={{ fill: 'var(--color-text-secondary)', fontSize: 11 }} />
            <PolarRadiusAxis angle={30} domain={[0, 100]} tick={false} axisLine={false} />
            {students.map((st, i) => (
              <Radar key={i} name={st.name || `S${i+1}`} dataKey={st.name || `S${i+1}`}
                stroke={COLORS[i]} fill={COLORS[i]} fillOpacity={0.12} strokeWidth={2} />
            ))}
            <Legend wrapperStyle={{ fontSize: 12 }} />
            <Tooltip
              contentStyle={{ background: '#111827', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 8, fontSize: 12 }}
              labelStyle={{ color: '#e2e8f0' }} />
          </RadarChart>
        </ResponsiveContainer>
      </div>

      {/* ── BAR CHART ───────────────────────────────────── */}
      <div style={S.card}>
        <div style={{ fontSize: 13, fontWeight: 600, marginBottom: 14 }}>Side-by-Side Metric Comparison</div>
        <ResponsiveContainer width="100%" height={210}>
          <BarChart data={barData} margin={{ left: -10 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.05)" />
            <XAxis dataKey="name" tick={{ fill: 'var(--color-text-secondary)', fontSize: 10 }} />
            <YAxis tick={{ fill: 'var(--color-text-secondary)', fontSize: 10 }} />
            <Tooltip contentStyle={{ background: '#111827', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 8, fontSize: 12 }} />
            <Legend wrapperStyle={{ fontSize: 12 }} />
            {students.map((st, i) => (
              <Bar key={i} dataKey={st.name || `S${i+1}`} fill={COLORS[i]} radius={[3,3,0,0]} />
            ))}
          </BarChart>
        </ResponsiveContainer>
      </div>

      {/* ── PICKER MODAL ────────────────────────────────── */}
      {pickerFor !== null && (
        <StudentPicker
          targetIdx={pickerFor}
          targetColor={COLORS[pickerFor]}
          onSelect={st => loadFromDataset(st, pickerFor)}
          onClose={() => setPickerFor(null)}
        />
      )}
    </div>
  );
}